/* Production accounts and administration. Demo data is never read or submitted here. */
if(location.pathname==='/admin'&&!location.hash)history.replaceState(null,'','#portal/overview');
const portalRender=render,portalBind=bind,portalShell=updateShell;
let accountStatus=null,accountStatusFailed=false,schoolData=null,schoolUsers=[],schoolLoading=false,schoolFailure='',editorState=null,learningData=null,learningLoading=false;
const labels={users:['Users','ผู้ใช้'],courses:['Courses','หลักสูตร'],assignments:['Course Assignments','มอบหมายหลักสูตร'],links:['Parent–Student Links','เชื่อมผู้ปกครอง–นักเรียน'],assessments:['Assessments','แบบทดสอบ'],events:['Events','กิจกรรม'],registrations:['Registrations','การลงทะเบียน']};
const label=k=>labels[k]?t(...labels[k]):k;
const datetime=v=>v?new Date(new Date(v).getTime()-new Date(v).getTimezoneOffset()*60000).toISOString().slice(0,16):'';
const formatted=v=>v?new Intl.DateTimeFormat(lang==='th'?'th-TH':'en-GB',{dateStyle:'medium'}).format(new Date(v)):t('Unlimited','ไม่จำกัด');
function accountMessage(code){const m={invalid_login:['Email or password is incorrect.','อีเมลหรือรหัสผ่านไม่ถูกต้อง'],password_length:['Use a password between 15 and 128 characters.','ใช้รหัสผ่านความยาว 15 ถึง 128 ตัวอักษร'],rate_limit:['Too many attempts. Please try again in 15 minutes.','พยายามหลายครั้งเกินไป โปรดลองใหม่ใน 15 นาที'],email_not_configured:['Email delivery is not configured. No email was sent.','ยังไม่ได้ตั้งค่าการส่งอีเมล ไม่มีการส่งอีเมล'],email_delivery_failed:['The email provider could not send the invitation. The account remains saved.','ผู้ให้บริการอีเมลส่งคำเชิญไม่สำเร็จ บัญชียังคงบันทึกอยู่'],invalid_token:['This one-time link is invalid or expired. Request a new link.','ลิงก์ใช้ครั้งเดียวไม่ถูกต้องหรือหมดอายุ โปรดขอลิงก์ใหม่'],setup_closed:['Initial setup is already complete. Please log in.','ตั้งค่าเริ่มต้นแล้ว โปรดเข้าสู่ระบบ'],email_exists:['An account with this email already exists.','มีบัญชีอีเมลนี้แล้ว'],forbidden:['You do not have permission for this action.','คุณไม่มีสิทธิ์ดำเนินการนี้'],unauthorized:['Please log in to continue.','โปรดเข้าสู่ระบบเพื่อดำเนินการต่อ'],conflict:['This record changed in another session. Reload before saving again.','ข้อมูลเปลี่ยนในเซสชันอื่น โปรดโหลดใหม่ก่อนบันทึก'],own_access:['You cannot remove your own administrator access.','คุณไม่สามารถยกเลิกสิทธิ์ผู้ดูแลของตนเอง'],last_admin:['Keep at least one active administrator.','ต้องมีผู้ดูแลที่ใช้งานได้อย่างน้อยหนึ่งคน'],password_not_set:['The invited user must set a password before activation.','ผู้ได้รับเชิญต้องตั้งรหัสผ่านก่อนเปิดใช้งาน'],invalid_reference:['Choose an existing user or course with the appropriate role.','เลือกผู้ใช้หรือหลักสูตรที่มีอยู่และมีบทบาทเหมาะสม'],invalid_date:['The dates do not form a valid range.','ช่วงวันที่ไม่ถูกต้อง'],duplicate_assignment:['This student already has an assignment for this course. Edit that assignment instead.','นักเรียนมีการมอบหมายหลักสูตรนี้แล้ว โปรดแก้ไขรายการเดิม'],duplicate_link:['This relationship already exists. Edit the existing link.','มีความสัมพันธ์นี้แล้ว โปรดแก้ไขรายการเดิม'],event_full:['This event is at capacity.','กิจกรรมนี้เต็มแล้ว'],relationship_not_verified:['Confirm that you have verified the relationship.','ยืนยันว่าคุณตรวจสอบความสัมพันธ์แล้ว'],invalid:['Please check the required fields and values.','โปรดตรวจสอบช่องที่จำเป็นและข้อมูล'],unavailable:['The service is unavailable. Please try again.','ไม่สามารถใช้บริการได้ โปรดลองอีกครั้ง']};return m[code]?t(...m[code]):errorText(code);}
function passwordFields(confirm=false){return `<label>${t('Password','รหัสผ่าน')}<div class="password-field"><input name="password" type="password" required minlength="15" maxlength="128" autocomplete="${confirm?'new-password':'current-password'}"><button type="button" data-show-password aria-pressed="false">${t('Show','แสดง')}</button></div></label>${confirm?field('confirm',t('Confirm password','ยืนยันรหัสผ่าน'),'','password')+`<p class="service-note">${t('Use at least 15 characters. A long, unique passphrase works well. Never share it in chat.','ใช้อย่างน้อย 15 ตัวอักษร เลือกวลีรหัสผ่านที่ยาวและไม่ซ้ำ ห้ามส่งรหัสผ่านในแชต')}</p>`:''}`;}
function authLayout(title,body){return `<div class="container"><section class="secure-auth"><div class="eyebrow">HEADSTART ACADEMICS</div><h1>${title}</h1><div class="auth-box">${body}</div></section></div>`;}
schoolLogin=function(){return authLayout(t('Log In','เข้าสู่ระบบ'),`<form id="real-login">${field('email',t('Email','อีเมล'),'','email')}${passwordFields()}<div class="form-error" role="alert"></div><button class="primary">${t('Log In','เข้าสู่ระบบ')}</button></form><div class="auth-switch"><a class="text-link" href="#reset">${t('Forgot Password?','ลืมรหัสผ่าน?')}</a><a class="text-link" href="#register">${t('Create Account','สร้างบัญชี')}</a></div>${accountStatus?.setupAllowed?`<div class="setup-highlight"><b>${t('Your administrator setup is ready','พร้อมตั้งค่าบัญชีผู้ดูแลของคุณ')}</b><p>${esc(accountStatus.setupEmail)}</p>${button(t('Set my administrator password','ตั้งรหัสผ่านผู้ดูแลของฉัน'),'setup')}</div>`:''}${accountStatusFailed?notice(t('Account service could not be reached. Try reloading.','ติดต่อบริการบัญชีไม่ได้ โปรดลองโหลดใหม่'),true):''}<hr><p>${t('Want to explore first?','ต้องการลองสำรวจก่อน?')} <a class="text-link" href="#demo">${t('Explore Demo','สำรวจระบบสาธิต')}</a></p><p class="service-note">${t('The demo is separate from school accounts.','ระบบสาธิตแยกจากบัญชีโรงเรียน')}</p>`);};
accountScreen=function(kind){if(kind==='reset')return authLayout(t('Reset your password','รีเซ็ตรหัสผ่าน'),`<form id="real-reset">${field('email',t('Account email','อีเมลบัญชี'),'','email')}<div class="form-error" role="alert"></div><button class="primary" ${!accountStatus?.emailDelivery?'disabled':''}>${t('Send reset link','ส่งลิงก์รีเซ็ต')}</button></form>${!accountStatus?.emailDelivery?notice(t('Email delivery is not configured. No reset email can be sent yet.','ยังไม่ได้ตั้งค่าการส่งอีเมล จึงยังส่งอีเมลรีเซ็ตไม่ได้'),true):''}${accountStatus?.recoveryAllowed?`<div class="setup-highlight"><h3>${t('Verified owner recovery','กู้คืนด้วยบัญชีเจ้าของที่ยืนยันแล้ว')}</h3><p>${t('Your existing verified site-owner identity can securely reset your own administrator password.','บัญชีเจ้าของเว็บไซต์ที่ยืนยันแล้วของคุณสามารถรีเซ็ตรหัสผ่านผู้ดูแลของตนเองได้อย่างปลอดภัย')}</p>${button(t('Reset my administrator password','รีเซ็ตรหัสผ่านผู้ดูแลของฉัน'),'recovery')}</div>`:''}<a class="text-link" href="#login">${t('Back to Log In','กลับไปเข้าสู่ระบบ')}</a>`);
return authLayout(t('Create Account','สร้างบัญชี'),`<form id="real-register">${field('name',t('Full name','ชื่อและนามสกุล'))}${field('email',t('Email','อีเมล'),'','email')}${selectField('role',t('Account type','ประเภทบัญชี'),[['student',roleName('student')],['parent',roleName('parent')]],'student')}<p>${t('We will email a one-time link to verify your email and set your password. Parent access requires administrator-verified links.','เราจะส่งลิงก์ใช้ครั้งเดียวเพื่อยืนยันอีเมลและตั้งรหัสผ่าน สิทธิ์ผู้ปกครองต้องให้ผู้ดูแลยืนยันความสัมพันธ์')}</p><div class="form-error" role="alert"></div><button class="primary" ${!accountStatus?.emailDelivery?'disabled':''}>${t('Request account','ขอสร้างบัญชี')}</button></form>${!accountStatus?.emailDelivery?notice(t('Email delivery is not configured. Contact the school to request an account.','ยังไม่ได้ตั้งค่าการส่งอีเมล โปรดติดต่อโรงเรียนเพื่อขอบัญชี'),true):''}<a class="text-link" href="#login">${t('Back to Log In','กลับไปเข้าสู่ระบบ')}</a>`);};
function setupScreen(mode){if(!accountStatus)return authLayout(t('Account setup','ตั้งค่าบัญชี'),notice(accountStatusFailed?t('Account service unavailable. Reload to retry.','บริการบัญชีไม่พร้อม โปรดโหลดใหม่'):t('Checking your verified identity…','กำลังตรวจสอบตัวตนที่ยืนยัน…')));const tokenMode=mode==='set-password',allowed=tokenMode||(mode==='setup'?accountStatus.setupAllowed:accountStatus.recoveryAllowed);if(!allowed)return authLayout(t('Protected account setup','การตั้งค่าบัญชีที่ได้รับการป้องกัน'),`<p>${t('This setup is only available to the verified site owner. If setup is complete, use Log In.','การตั้งค่านี้เฉพาะเจ้าของเว็บไซต์ที่ยืนยันตัวตนแล้ว หากตั้งค่าเสร็จ โปรดเข้าสู่ระบบ')}</p><a class="button" href="/signin-with-chatgpt?return_to=${encodeURIComponent('/#'+mode)}" target="_top">${t('Verify site-owner identity','ยืนยันตัวตนเจ้าของเว็บไซต์')}</a><p><a href="#login">${t('Log In','เข้าสู่ระบบ')}</a></p>`);
return authLayout(t('Set your password','ตั้งรหัสผ่านของคุณ'),`<p>${tokenMode?t('Use your one-time invitation or reset link.','ใช้ลิงก์คำเชิญหรือรีเซ็ตแบบใช้ครั้งเดียว'):esc(accountStatus.setupEmail)}</p><form id="real-set-password" data-mode="${mode}">${passwordFields(true)}<div class="form-error" role="alert"></div><button class="primary">${t('Set password securely','ตั้งรหัสผ่านอย่างปลอดภัย')}</button></form><p class="service-note">${mode==='recovery'?t('This resets your own password and signs out all existing school sessions.','รีเซ็ตรหัสผ่านของคุณและออกจากเซสชันโรงเรียนทั้งหมด'):t('Your password is stored only as a salted password hash.','จัดเก็บรหัสผ่านเป็นค่าแฮชที่มี salt เท่านั้น')}</p>`);}
function selectField(name,title,options,value){return `<label>${title}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function biFields(prefix,title,value={en:'',th:''},long=false,required=true){const input=(l)=>long?`<label>${title} · ${l==='en'?'English':'ไทย'}<textarea name="${prefix}_${l}" ${l==='en'&&required?'required':''} maxlength="6000">${esc(value?.[l]||'')}</textarea></label>`:field(prefix+'_'+l,title+' · '+(l==='en'?'English':'ไทย'),value?.[l]||'','text',l==='en'&&required);return `<div class="two">${input('en')}${input('th')}</div>`;}
function userOptions(role){return schoolUsers.filter(u=>u.roles.includes(role)&&u.status!=='disabled').map(u=>[u.id,u.name+' · '+u.email]);}
const courseOptions=()=>schoolData.courses.map(c=>[c.id,tx(c.title)]);
const uName=id=>schoolUsers.find(u=>u.id===id)?.name||id;
const cName=id=>tx(schoolData.courses.find(c=>c.id===id)?.title)||id;
function editButton(kind,id){return `<button class="button small" data-admin-edit="${kind}" data-id="${id}">${t('Edit','แก้ไข')}</button>`;}
function loadSchool(force=false){if(schoolLoading||schoolData&&!force)return;schoolLoading=true;schoolFailure='';Promise.all([api('/api/admin/school'),api('/api/admin/users')]).then(([d,u])=>{schoolData=d;schoolUsers=u.users}).catch(e=>{schoolFailure=accountMessage(e.message);if(e.message==='forbidden'){session={role:'visitor',roles:[],courses:[]};schoolData=null;schoolUsers=[];}}).finally(()=>{schoolLoading=false;render()});}
function productionBody(page){if(['content','appearance','media'].includes(page)){demo.role=null;return page==='content'?editorPage():page==='appearance'?appearancePage():mediaPage();}if(page==='settings')return `<div class="panel"><h2>${t('Your account','บัญชีของคุณ')}</h2><p>${esc(session.name||'')} · ${esc(session.email||'')}</p><p>${t('Assigned permissions','สิทธิ์ที่ได้รับ')}: ${allowedRealRoles().map(roleName).join(', ')}</p><div class="admin-actions"><a class="button" href="#reset">${t('Reset password','รีเซ็ตรหัสผ่าน')}</a><button class="button" data-school-logout>${t('Log Out','ออกจากระบบ')}</button></div><h3>${t('Email delivery','การส่งอีเมล')}</h3><p>${accountStatus?.emailDelivery?t('Mail provider configured. Sending is confirmed only when the provider accepts a request.','ตั้งค่าผู้ให้บริการอีเมลแล้ว ยืนยันการส่งเมื่อผู้ให้บริการรับคำขอเท่านั้น'):t('Not configured. Invitations and email resets cannot be sent.','ยังไม่ได้ตั้งค่า จึงส่งคำเชิญและอีเมลรีเซ็ตไม่ได้')}</p><p>${t('To enable email: configure a Resend account with a verified sending domain, then securely set RESEND_API_KEY and EMAIL_FROM in the website’s server environment and redeploy. Never place the API key in public content.','เปิดใช้อีเมลโดยตั้งค่าบัญชี Resend พร้อมโดเมนผู้ส่งที่ยืนยัน แล้วกำหนด RESEND_API_KEY และ EMAIL_FROM อย่างปลอดภัยในระบบเซิร์ฟเวอร์และเผยแพร่ใหม่ ห้ามใส่คีย์ในเนื้อหาสาธารณะ')}</p><h3>${t('Video hosting','การจัดเก็บวิดีโอ')}</h3><p>${t('Add prerecorded video URLs from your approved video host. Use restricted hosting for private course videos. No live-class tools are included.','เพิ่ม URL วิดีโอที่บันทึกไว้จากผู้ให้บริการที่ได้รับอนุมัติ ใช้โฮสต์ที่จำกัดสิทธิ์สำหรับวิดีโอส่วนตัว ไม่มีเครื่องมือสอนสด')}</p></div>`;
if(!schoolData){if(!schoolLoading&&!schoolFailure)loadSchool();return `<div class="panel">${schoolFailure?notice(esc(schoolFailure),true)+`<button class="button" data-reload-school>${t('Try again','ลองใหม่')}</button>`:notice(t('Loading school records…','กำลังโหลดข้อมูลโรงเรียน…'))}</div>`;}if(editorState)return recordEditor();
const kind=page==='access'?'assignments':page;
if(page==='overview')return `<div class="admin-heading"><div><h2>${t('School administration','การบริหารโรงเรียน')}</h2><p>${t('Live school records. No sample figures.','ข้อมูลจริงของโรงเรียน ไม่มีตัวเลขตัวอย่าง')}</p></div><div class="admin-actions"><button class="primary" data-admin-new="users">${t('Add User','เพิ่มผู้ใช้')}</button><button class="button" data-admin-new="courses">${t('Create Course','สร้างหลักสูตร')}</button><button class="button" data-admin-new="assignments">${t('Assign Course','มอบหมายหลักสูตร')}</button></div></div><div class="admin-summary">${[[schoolUsers.filter(u=>u.roles.includes('student')&&u.status==='active').length,t('Active students','นักเรียนที่ใช้งาน')],[schoolData.courses.filter(c=>c.status==='published').length,t('Published courses','หลักสูตรที่เผยแพร่')],[schoolUsers.filter(u=>u.status==='invited').length,t('Pending password setup','รอตั้งรหัสผ่าน')]].map(([n,l])=>`<div class="panel"><strong>${n}</strong>${l}</div>`).join('')}</div><section class="panel"><h3>${t('Students awaiting assignment','นักเรียนที่รอมอบหมายหลักสูตร')}</h3>${schoolUsers.filter(u=>u.roles.includes('student')&&!schoolData.assignments.some(a=>a.student===u.id&&a.active)).map(u=>`<p>${esc(u.name)}</p>`).join('')||t('No students awaiting assignment.','ไม่มีนักเรียนที่รอมอบหมาย')}</section><section class="panel"><h3>${t('Upcoming events','กิจกรรมที่กำลังจะมาถึง')}</h3>${schoolData.events.filter(e=>Date.parse(e.start)>Date.now()&&e.status==='published').map(e=>`<p>${esc(tx(e.title))} · ${formatted(e.start)} · ${schoolData.registrations.filter(r=>r.event===e.id&&r.status==='confirmed').length}/${e.capacity}</p>`).join('')||t('No upcoming published events.','ไม่มีกิจกรรมที่เผยแพร่ในเร็ว ๆ นี้')}</section>${reportsBody()}`;
if(page==='reports')return reportsBody();
if(labels[kind]){const rows=kind==='users'?schoolUsers:schoolData[kind];let headers,values;if(kind==='users'){headers=[t('Name','ชื่อ'),t('Email','อีเมล'),t('Roles','บทบาท'),t('Status','สถานะ'),''];values=rows.map(u=>[esc(u.name),esc(u.email),u.roles.map(roleName).join(', '),statusText(u.status),editButton(kind,u.id)]);}else if(kind==='courses'){headers=[t('Course','หลักสูตร'),t('Teaching language','ภาษาที่สอน'),t('Lessons','บทเรียน'),t('Status','สถานะ'),''];values=rows.map(c=>[esc(tx(c.title)),esc(c.language.toUpperCase()),c.lessons.length,statusText(c.status),editButton(kind,c.id)]);}else if(kind==='assignments'){headers=[t('Student','นักเรียน'),t('Course','หลักสูตร'),t('Ends','สิ้นสุด'),t('Access','สิทธิ์'),''];values=rows.map(a=>[esc(uName(a.student)),esc(cName(a.course)),formatted(a.ends),a.active?t('Assigned','มอบหมายแล้ว'):t('Revoked','เพิกถอน'),editButton(kind,a.id)]);}else if(kind==='links'){headers=[t('Parent','ผู้ปกครอง'),t('Student','นักเรียน'),t('Status','สถานะ'),''];values=rows.map(l=>[esc(uName(l.parent)),esc(uName(l.student)),l.active?t('Verified','ยืนยันแล้ว'):t('Revoked','เพิกถอน'),editButton(kind,l.id)]);}else if(kind==='assessments'){headers=[t('Assessment','แบบทดสอบ'),t('Course','หลักสูตร'),t('Pass score','คะแนนผ่าน'),t('Status','สถานะ'),''];values=rows.map(a=>[esc(tx(a.title)),esc(cName(a.course)),a.passScore+'%',statusText(a.status),editButton(kind,a.id)]);}else if(kind==='events'){headers=[t('Event','กิจกรรม'),t('Date','วันที่'),t('Registrations','การลงทะเบียน'),t('Status','สถานะ'),''];values=rows.map(e=>[esc(tx(e.title)),formatted(e.start),schoolData.registrations.filter(r=>r.event===e.id&&r.status==='confirmed').length+'/'+e.capacity,statusText(e.status),editButton(kind,e.id)]);}else{headers=[t('Name','ชื่อ'),t('Email','อีเมล'),t('Event','กิจกรรม'),t('Status','สถานะ'),''];values=rows.map(r=>[esc(r.name),esc(r.email),esc(tx(schoolData.events.find(e=>e.id===r.event)?.title)),statusText(r.status),editButton(kind,r.id)]);}return `<div class="admin-heading"><h2>${label(kind)}</h2><button class="primary" data-admin-new="${kind}">${t('Add new','เพิ่มใหม่')}</button></div>${kind==='events'?`<p><a class="text-link" href="#portal/registrations">${t('Manage registrations','จัดการการลงทะเบียน')} ↗</a></p>`:''}<div class="panel admin-table">${rows.length?table(headers,values):empty(t('No records yet','ยังไม่มีข้อมูล'),t('Create the first record using Add new.','สร้างรายการแรกด้วยปุ่มเพิ่มใหม่'))}</div>`;}return empty(t('Page not found','ไม่พบหน้า'),t('Choose a page from the menu.','เลือกหน้าจากเมนู'));}
function statusText(s){return t(...({active:['Active','ใช้งาน'],invited:['Invited — password pending','เชิญแล้ว — รอตั้งรหัสผ่าน'],disabled:['Disabled','ปิดใช้งาน'],draft:['Draft','ร่าง'],published:['Published','เผยแพร่'],archived:['Archived','เก็บถาวร'],confirmed:['Confirmed','ยืนยันแล้ว'],cancelled:['Cancelled','ยกเลิก']}[s]||[s,s]));}
function reportsBody(){const records=schoolData.assignments.map(a=>{const c=schoolData.courses.find(c=>c.id===a.course),completed=schoolData.progress.filter(p=>p.student===a.student&&p.course===a.course&&p.completed).length,results=schoolData.submissions.filter(s=>s.student===a.student&&s.course===a.course);return [esc(uName(a.student)),esc(tx(c?.title)),completed+'/'+(c?.lessons.length||0),results.length?results.map(r=>r.score===null?'—':r.score+'%').join(', '):'—'];});return `<div class="panel"><h3>${t('Learning progress and results','พัฒนาการและผลการเรียน')}</h3>${records.length?table([t('Student','นักเรียน'),t('Course','หลักสูตร'),t('Lessons complete','บทเรียนที่เสร็จ'),t('Results','ผลการเรียน')],records):empty(t('No learning records yet','ยังไม่มีข้อมูลการเรียน'),t('Reports use stored lesson completion and assessment submissions.','รายงานใช้ข้อมูลการเรียนจบบทเรียนและการส่งแบบทดสอบที่บันทึกไว้'))}<p class="service-note">${t('Lesson completion describes learning activity, not classroom attendance.','การเรียนจบบทเรียนเป็นกิจกรรมการเรียนรู้ ไม่ใช่การเข้าเรียนในห้องเรียน')}</p></div>`;}
function recordEditor(){const{kind,record:r}=editorState;let body='';if(kind==='users')body=`${field('name',t('Full name','ชื่อและนามสกุล'),r.name||'')}${r.id?`<p>${esc(r.email)}</p>`:field('email',t('Email','อีเมล'),'','email')}<h3>${t('Assigned roles','บทบาทที่มอบหมาย')}</h3><div class="check-row">${['student','teacher','parent','admin'].map(role=>`<label><input type="checkbox" name="roles" value="${role}" ${r.roles?.includes(role)?'checked':''}>${roleName(role)}</label>`).join('')}</div>${r.id?selectField('status',t('Account status','สถานะบัญชี'),['active','invited','disabled'].map(v=>[v,statusText(v)]),r.status):''}<p>${t('The user chooses their own password through a one-time email invitation. Saving this record does not send an invitation.','ผู้ใช้ตั้งรหัสผ่านเองผ่านคำเชิญอีเมลแบบใช้ครั้งเดียว การบันทึกรายการนี้ไม่ส่งคำเชิญ')}</p>${r.id&&r.status==='invited'?`<button type="button" class="button" data-send-invite="${r.id}" ${!accountStatus?.emailDelivery?'disabled':''}>${t('Send invitation email','ส่งอีเมลคำเชิญ')}</button><p>${!accountStatus?.emailDelivery?t('Email delivery must be configured first.','ต้องตั้งค่าการส่งอีเมลก่อน'):''}</p>`:''}`;
if(kind==='courses')body=`${biFields('title',t('Course title','ชื่อหลักสูตร'),r.title)}${biFields('description',t('Description','คำอธิบาย'),r.description,true)}<div class="two">${field('subject',t('Subject','วิชา'),r.subject||'')}${field('level',t('Grade / learning level','ระดับชั้น / ระดับการเรียน'),r.level||'')}</div><div class="two">${selectField('language',t('Teaching language','ภาษาที่สอน'),[['en','English'],['th','ไทย'],['both',t('English and Thai','อังกฤษและไทย')]],r.language||'en')}${selectField('status',t('Publication status','สถานะการเผยแพร่'),['draft','published','archived'].map(s=>[s,statusText(s)]),r.status||'draft')}</div><h3>${t('Assigned teachers','ครูที่มอบหมาย')}</h3><div class="check-row">${userOptions('teacher').map(([id,name])=>`<label><input name="teacherIds" value="${id}" type="checkbox" ${r.teacherIds?.includes(id)?'checked':''}>${esc(name)}</label>`).join('')||t('Add a teacher in Users first.','เพิ่มครูในหน้าผู้ใช้ก่อน')}</div><h3>${t('Modules & prerecorded lessons','หมวดและบทเรียนวิดีโอบันทึก')}</h3><p>${t('Interface language does not translate videos or attached documents. Use your school’s approved video hosting.','ภาษาอินเทอร์เฟซไม่แปลวิดีโอหรือเอกสารแนบ ใช้ผู้ให้บริการวิดีโอที่โรงเรียนอนุมัติ')}</p>${(r.lessons||[]).map((l,i)=>`<div class="admin-item"><h3>${t('Lesson','บทเรียน')} ${i+1}</h3>${biFields('l'+i+'module',t('Module','หมวด'),l.module)}${biFields('l'+i+'title',t('Title','ชื่อ'),l.title)}${biFields('l'+i+'text',t('Lesson text','เนื้อหาบทเรียน'),l.text,true,false)}${field('l'+i+'videoUrl',t('Prerecorded video URL (HTTPS)','URL วิดีโอที่บันทึกไว้ (HTTPS)'),l.videoUrl||'','url',false)}${field('l'+i+'materialUrl',t('Downloadable material URL (HTTPS)','URL เอกสารดาวน์โหลด (HTTPS)'),l.materialUrl||'','url',false)}${field('l'+i+'minutes',t('Duration in minutes','ระยะเวลาเป็นนาที'),l.minutes||0,'number',false)}<label class="question-option"><input type="checkbox" name="l${i}preview" ${l.preview?'checked':''}>${t('Approved public preview','บทเรียนทดลองสาธารณะที่อนุมัติแล้ว')}</label><button type="button" class="button small" data-remove-lesson="${i}">${t('Remove lesson','นำบทเรียนออก')}</button></div>`).join('')}<button type="button" class="button" id="add-lesson">${t('Add lesson','เพิ่มบทเรียน')}</button>`;
if(kind==='assignments')body=`${selectField('student',t('Student','นักเรียน'),userOptions('student'),r.student)}${selectField('course',t('Course','หลักสูตร'),courseOptions(),r.course)}${selectField('mode',t('Access period','ระยะเวลาสิทธิ์'),[['fixed',t('Fixed date range','ช่วงวันที่กำหนด')],['duration',t('Duration from assignment','ระยะเวลาจากการมอบหมาย')],['unlimited',t('Unlimited — explicitly granted','ไม่จำกัด — กำหนดโดยชัดแจ้ง')]],r.mode||'fixed')}${field('starts',t('Starts','เริ่ม'),datetime(r.starts)||datetime(new Date()),'datetime-local')}${field('ends',t('Ends (fixed range)','สิ้นสุด (ช่วงวันที่กำหนด)'),datetime(r.ends),'datetime-local',false)}${field('days',t('Number of days (duration)','จำนวนวัน (ระยะเวลา)'),r.days||30,'number',false)}${selectField('active',t('Access','สิทธิ์'),[['true',t('Active','ใช้งาน')],['false',t('Revoked','เพิกถอน')]],String(r.active??true))}`;
if(kind==='links')body=`${selectField('parent',t('Parent / guardian','ผู้ปกครอง'),userOptions('parent'),r.parent)}${selectField('student',t('Student','นักเรียน'),userOptions('student'),r.student)}${field('verificationNote',t('Relationship verification reference','ข้อมูลอ้างอิงการยืนยันความสัมพันธ์'),r.verificationNote||'')}<label class="question-option"><input type="checkbox" name="verified" required ${r.verified?'checked':''}>${t('I verified that this parent is authorized to see this student’s information.','ฉันตรวจสอบแล้วว่าผู้ปกครองนี้มีสิทธิ์ดูข้อมูลนักเรียนนี้')}</label>${selectField('active',t('Access','สิทธิ์'),[['true',t('Active','ใช้งาน')],['false',t('Revoked','เพิกถอน')]],String(r.active??true))}`;
if(kind==='assessments')body=`${biFields('title',t('Assessment title','ชื่อแบบทดสอบ'),r.title)}${selectField('course',t('Course','หลักสูตร'),courseOptions(),r.course)}${selectField('type',t('Assessment type','ประเภทแบบทดสอบ'),[['placement',t('Placement','วัดระดับ')],['quiz',t('Quiz','แบบทดสอบย่อย')],['assignment',t('Assignment','งานที่มอบหมาย')],['pre-test',t('Pre-test','ก่อนเรียน')],['post-test',t('Post-test','หลังเรียน')]],r.type||'quiz')}<div class="two">${field('passScore',t('Pass score (%)','คะแนนผ่าน (%)'),r.passScore??60,'number')}${field('attemptLimit',t('Attempt limit','จำนวนครั้งที่อนุญาต'),r.attemptLimit??1,'number')}</div>${selectField('status',t('Status','สถานะ'),['draft','published','archived'].map(s=>[s,statusText(s)]),r.status||'draft')}<label class="question-option"><input type="checkbox" name="releaseAnswers" ${r.releaseAnswers?'checked':''}>${t('Release answers after submission','แสดงคำตอบหลังส่งแบบทดสอบ')}</label>${(r.questions||[]).map((q,i)=>`<div class="admin-item"><h3>${t('Question','คำถาม')} ${i+1}</h3>${selectField('q'+i+'type',t('Question type','ประเภทคำถาม'),[['multiple',t('Multiple choice','ปรนัย')],['written',t('Written answer','คำตอบแบบเขียน')]],q.type||'multiple')}${biFields('q'+i+'prompt',t('Question','คำถาม'),q.prompt,true)}${[0,1,2,3].map(n=>biFields('q'+i+'option'+n,t('Option','ตัวเลือก')+' '+(n+1),q.options?.[n],false,false)).join('')}${selectField('q'+i+'answer',t('Correct option (multiple choice only)','ตัวเลือกที่ถูกต้อง (เฉพาะปรนัย)'),[0,1,2,3].map(n=>[String(n),String(n+1)]),String(q.answer??0))}</div>`).join('')}<button type="button" class="button" id="add-question">${t('Add question','เพิ่มคำถาม')}</button>`;
if(kind==='events')body=`${biFields('title',t('Event title','ชื่อกิจกรรม'),r.title)}${biFields('description',t('Description','คำอธิบาย'),r.description,true)}${biFields('location',t('Location','สถานที่'),r.location)}<div class="two">${field('start',t('Date & time','วันที่และเวลา'),datetime(r.start),'datetime-local')}${field('deadline',t('Registration deadline','ปิดรับลงทะเบียน'),datetime(r.deadline),'datetime-local')}</div>${field('capacity',t('Capacity','จำนวนที่นั่ง'),r.capacity||20,'number')}${selectField('status',t('Status','สถานะ'),['draft','published','archived'].map(s=>[s,statusText(s)]),r.status||'draft')}`;
if(kind==='registrations')body=`${selectField('event',t('Event','กิจกรรม'),schoolData.events.map(e=>[e.id,tx(e.title)]),r.event)}${field('name',t('Full name','ชื่อและนามสกุล'),r.name||'')}${field('email',t('Email','อีเมล'),r.email||'','email')}${field('phone',t('Phone (optional)','โทรศัพท์ (ไม่บังคับ)'),r.phone||'','tel',false)}${selectField('status',t('Registration status','สถานะการลงทะเบียน'),['confirmed','cancelled'].map(s=>[s,statusText(s)]),r.status||'confirmed')}`;
return `<section class="panel admin-editor"><h2>${r.id?t('Edit','แก้ไข'):t('Add','เพิ่ม')} · ${label(kind)}</h2><form id="production-editor">${body}<div class="form-error" role="alert"></div><div class="admin-actions"><button class="primary">${t('Save','บันทึก')}</button><button type="button" class="button" id="cancel-record">${t('Cancel','ยกเลิก')}</button></div></form></section>`;}
function readEditor(){const f=new FormData($('#production-editor')),r=editorState.record,k=editorState.kind,bi=p=>({en:f.get(p+'_en')||'',th:f.get(p+'_th')||''}),get=n=>f.get(n)||'';if(k==='users')return {...r,name:get('name'),email:r.email||get('email'),roles:f.getAll('roles'),status:r.id?get('status'):'invited'};if(k==='courses')return {...r,title:bi('title'),description:bi('description'),subject:get('subject'),level:get('level'),language:get('language'),status:get('status'),teacherIds:f.getAll('teacherIds'),lessons:(r.lessons||[]).map((l,i)=>({...l,module:bi('l'+i+'module'),title:bi('l'+i+'title'),text:bi('l'+i+'text'),videoUrl:get('l'+i+'videoUrl'),materialUrl:get('l'+i+'materialUrl'),minutes:+get('l'+i+'minutes'),preview:f.has('l'+i+'preview')}))};if(k==='assignments')return {...r,student:get('student'),course:get('course'),mode:get('mode'),starts:get('starts')?new Date(get('starts')).toISOString():'',ends:get('ends')?new Date(get('ends')).toISOString():'',days:+get('days'),active:get('active')==='true'};if(k==='links')return {...r,parent:get('parent'),student:get('student'),verified:f.has('verified'),verificationNote:get('verificationNote'),active:get('active')==='true'};if(k==='assessments')return {...r,title:bi('title'),course:get('course'),type:get('type'),status:get('status'),passScore:+get('passScore'),attemptLimit:+get('attemptLimit'),releaseAnswers:f.has('releaseAnswers'),questions:(r.questions||[]).map((q,i)=>({...q,type:get('q'+i+'type'),prompt:bi('q'+i+'prompt'),options:[0,1,2,3].map(n=>bi('q'+i+'option'+n)),answer:+get('q'+i+'answer')}))};if(k==='events')return {...r,title:bi('title'),description:bi('description'),location:bi('location'),start:get('start')?new Date(get('start')).toISOString():'',deadline:get('deadline')?new Date(get('deadline')).toISOString():'',capacity:+get('capacity'),status:get('status')};return {...r,event:get('event'),name:get('name'),email:get('email'),phone:get('phone'),status:get('status')};}
const freshPair=()=>({en:'',th:''});
function freshRecord(kind){return kind==='courses'?{title:freshPair(),description:freshPair(),teacherIds:[],lessons:[]}:kind==='assessments'?{title:freshPair(),questions:[]}:kind==='users'?{roles:['student']}:{};}
function portalFrame(body,page){const r=realRole(),menus=menuFor(r);return `<div class="portal portal-v3"><aside class="sidebar"><div class="profile"><b>${esc(session.name||roleName(r))}</b><small>${roleName(r)}</small></div>${menus.map(([id,title])=>`<a href="#portal/${id}" class="${page===id?'active':''}" data-production-nav>${title}</a>`).join('')}<a href="/">← ${t('School website','เว็บไซต์โรงเรียน')}</a></aside><div class="portal-content"><div class="portal-topbar"><h1>${page==='registrations'?label('registrations'):menus.find(m=>m[0]===page)?.[1]||t('Dashboard','แดชบอร์ด')}</h1><div class="portal-controls"><div class="language-switch">${['en','th'].map(l=>`<button data-portal-lang="${l}" aria-pressed="${l===lang}">${l.toUpperCase()}</button>`).join('')}</div><button class="button small" data-school-logout>${t('Log Out','ออกจากระบบ')}</button></div></div>${allowedRealRoles().length>1?selectField('real-role',t('Authorized role','บทบาทที่ได้รับอนุญาต'),allowedRealRoles().map(r=>[r,roleName(r)]),r):''}${body}</div></div>`;}
realPortal=function(page='overview'){if(!authChecked)return authLayout(t('Checking your account…','กำลังตรวจสอบบัญชี…'),'');if(!realRole()){history.replaceState(null,'','#login?next='+encodeURIComponent('portal/'+page));return schoolLogin();}return portalFrame(realRole()==='admin'?productionBody(page):nonAdminBody(page),page);};
function nonAdminBody(page){if(page==='profile')return `<div class="panel"><h2>${esc(session.name)}</h2><p>${esc(session.email)}</p>${button(t('Reset password','รีเซ็ตรหัสผ่าน'),'reset')}</div>`;if(!learningData){if(!learningLoading&&!schoolFailure){learningLoading=true;api('/api/learning').then(d=>learningData=d).catch(e=>schoolFailure=accountMessage(e.message)).finally(()=>{learningLoading=false;render()});}return notice(schoolFailure||t('Loading your authorized learning records…','กำลังโหลดข้อมูลการเรียนที่คุณมีสิทธิ์…'));}return `<div class="panel"><h2>${t('Your authorized courses','หลักสูตรที่คุณมีสิทธิ์')}</h2>${learningData.courses.length?learningData.courses.map(c=>`<article class="admin-item"><h3>${esc(tx(c.title))}</h3><p>${esc(tx(c.description))}</p><p>${t('Teaching language','ภาษาที่สอน')}: ${esc(c.language.toUpperCase())}</p>${c.lessons.map(l=>`<details><summary>${esc(tx(l.title))}</summary><p>${esc(tx(l.text))}</p>${l.videoUrl?`<video class="admin-learn-video" controls preload="metadata" src="${esc(l.videoUrl)}"></video>`:''}${l.materialUrl?`<a class="text-link" href="${esc(l.materialUrl)}" target="_blank" rel="noopener noreferrer">${t('Download material','ดาวน์โหลดเอกสาร')}</a>`:''}</details>`).join('')}</article>`).join(''):empty(t('No assigned courses','ยังไม่มีหลักสูตรที่มอบหมาย'),t('Contact the school to request access. Parent records require an approved relationship.','ติดต่อโรงเรียนเพื่อขอสิทธิ์ ข้อมูลผู้ปกครองต้องยืนยันความสัมพันธ์ก่อน'))}</div>`;}
updateShell=function(){portalShell();if(session.school&&realRole()){$('.signin').href=realRole()==='admin'?'/admin#portal/overview':'#portal/overview';document.querySelectorAll('a[href^="/signout-with-chatgpt"]').forEach(a=>{a.href='#login';a.dataset.schoolLogout='';});}if(route()[0]==='portal'&&session.school){$('.demo-bar').innerHTML=`HEADSTART ACADEMICS <span>${t('Secure school administration','ระบบโรงเรียนที่ปลอดภัย')}</span><a href="/">${t('School website','เว็บไซต์โรงเรียน')} ↗</a>`;}};
render=function(){const p=route()[0];if(['setup','recovery','set-password'].includes(p)){updateShell();main.innerHTML=setupScreen(p);bind();installValidation();return;}portalRender();};
async function refreshAccounts(){try{accountStatus=await api('/api/auth/status');accountStatusFailed=false;}catch{accountStatusFailed=true;}render();}
async function formAction(form,task){if(!validateForm(form))return;const button=form.querySelector('button[type=submit],button.primary'),message=form.querySelector('.form-error');if(button?.disabled)return;const old=button?.textContent;if(button){button.disabled=true;button.textContent=t('Please wait…','กรุณารอสักครู่…');}message.textContent='';try{await task(new FormData(form));}catch(e){message.textContent=accountMessage(e.message);}finally{if(button){button.disabled=false;button.textContent=old;}}}
bind=function(){portalBind();document.querySelectorAll('[data-show-password]').forEach(b=>b.onclick=()=>{const p=b.parentElement.querySelector('input');p.type=p.type==='password'?'text':'password';b.textContent=p.type==='password'?t('Show','แสดง'):t('Hide','ซ่อน');b.setAttribute('aria-pressed',String(p.type==='text'));});
if($('#real-login'))$('#real-login').onsubmit=e=>{e.preventDefault();formAction(e.target,async f=>{const password=f.get('password');await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:f.get('email'),password})});e.target.reset();await loadSite();schoolData=null;learningData=null;const dest=nextPath();location.href=session.role==='admin'?'/admin#'+dest:'/#'+dest;});};
if($('#real-set-password'))$('#real-set-password').onsubmit=e=>{e.preventDefault();formAction(e.target,async f=>{if(f.get('password')!==f.get('confirm'))throw new Error('password_mismatch');const mode=e.target.dataset.mode,token=new URLSearchParams(location.hash.split('?')[1]||'').get('token');await api('/api/auth/'+(mode==='setup'?'setup':mode==='recovery'?'recover-owner':'set-password'),{method:'POST',body:JSON.stringify({password:f.get('password'),token})});e.target.reset();if(mode==='set-password'){history.replaceState(null,'','/#login');render();toast('Password set. Please log in.','ตั้งรหัสผ่านแล้ว โปรดเข้าสู่ระบบ');}else{await loadSite();location.href='/admin#portal/overview';}});};
if($('#real-reset'))$('#real-reset').onsubmit=e=>{e.preventDefault();formAction(e.target,async f=>{await api('/api/auth/reset-request',{method:'POST',body:JSON.stringify({email:f.get('email')})});e.target.reset();e.target.querySelector('.form-error').textContent=t('If the account is eligible, a reset email has been requested. Check your inbox. Delivery is not confirmed here.','หากบัญชีเข้าเงื่อนไข ระบบขอส่งอีเมลรีเซ็ตแล้ว โปรดตรวจกล่องจดหมาย หน้านี้ไม่ยืนยันการจัดส่ง');});};
if($('#real-register'))$('#real-register').onsubmit=e=>{e.preventDefault();formAction(e.target,async f=>{await api('/api/auth/register',{method:'POST',body:JSON.stringify({name:f.get('name'),email:f.get('email'),role:f.get('role')})});e.target.reset();e.target.querySelector('.form-error').textContent=t('Request received. If eligible, you will receive a one-time setup email.','รับคำขอแล้ว หากเข้าเงื่อนไข คุณจะได้รับอีเมลตั้งค่าแบบใช้ครั้งเดียว');});};
document.querySelectorAll('[data-school-logout]').forEach(b=>b.onclick=async e=>{e.preventDefault();try{await api('/api/auth/logout',{method:'POST'});session={role:'visitor',roles:[],courses:[]};schoolData=null;schoolUsers=[];learningData=null;location.href='/#login';}catch(e){toast(accountMessage(e.message),accountMessage(e.message));}});
document.querySelectorAll('[data-admin-new]').forEach(b=>b.onclick=()=>{editorState={kind:b.dataset.adminNew,record:freshRecord(b.dataset.adminNew)};render();});document.querySelectorAll('[data-admin-edit]').forEach(b=>b.onclick=()=>{const kind=b.dataset.adminEdit;editorState={kind,record:structuredClone((kind==='users'?schoolUsers:schoolData[kind]).find(r=>r.id===b.dataset.id))};render();});document.querySelectorAll('[data-production-nav]').forEach(a=>a.addEventListener('click',()=>{editorState=null;}));if($('#cancel-record'))$('#cancel-record').onclick=()=>{editorState=null;render();};document.querySelectorAll('[data-reload-school]').forEach(b=>b.onclick=()=>loadSchool(true));
if($('#production-editor'))$('#production-editor').onsubmit=e=>{e.preventDefault();formAction(e.target,async()=>{const record=readEditor(),kind=editorState.kind,id=record.id;await api('/api/admin/'+(kind==='users'?'users':'school/'+kind)+(id?'/'+id:''),{method:id?(kind==='users'?'PATCH':'PUT'):'POST',body:JSON.stringify(kind==='users'?record:{record,etag:schoolData.etag})});editorState=null;schoolData=null;loadSchool(true);toast('Saved to school records.','บันทึกข้อมูลโรงเรียนแล้ว');render();});};
if($('#add-lesson'))$('#add-lesson').onclick=()=>{editorState.record=readEditor();editorState.record.lessons.push({module:{en:'Module 1',th:''},title:freshPair(),text:freshPair()});render();};document.querySelectorAll('[data-remove-lesson]').forEach(b=>b.onclick=()=>{editorState.record=readEditor();editorState.record.lessons.splice(+b.dataset.removeLesson,1);render();});if($('#add-question'))$('#add-question').onclick=()=>{editorState.record=readEditor();editorState.record.questions.push({type:'multiple',prompt:freshPair(),options:[freshPair(),freshPair(),freshPair(),freshPair()],answer:0});render();};
document.querySelectorAll('[data-send-invite]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/admin/users/'+b.dataset.sendInvite+'/invite',{method:'POST',body:'{}'});toast('Invitation accepted by the email provider.','ผู้ให้บริการอีเมลรับคำเชิญแล้ว');}catch(e){$('#production-editor .form-error').textContent=accountMessage(e.message);}finally{b.disabled=false;}});const roles=$('select[name="real-role"]');if(roles)roles.onchange=e=>{if(allowedRealRoles().includes(e.target.value)){activeRealRole=e.target.value;editorState=null;location.hash='portal/overview';render();}};
};
const simpleReports=reportsBody;
reportsBody=function(){return simpleReports()+schoolData.submissions.filter(s=>s.status==='pending').map(s=>`<section class="panel"><h3>${t('Review written work','ตรวจงานเขียน')} · ${esc(uName(s.student))}</h3><p>${esc(cName(s.course))}</p>${s.answers.map(a=>`<p>${esc(String(a))}</p>`).join('')}<form data-grade-submission="${s.id}">${field('score',t('Score (%)','คะแนน (%)'),'','number')}<label>${t('Feedback','ข้อเสนอแนะ')}<textarea name="feedback" required maxlength="6000"></textarea></label><div class="form-error" role="alert"></div><button class="primary">${t('Return score and feedback','ส่งคืนคะแนนและข้อเสนอแนะ')}</button></form></section>`).join('');};
const simpleLearning=nonAdminBody;
nonAdminBody=function(page){if(!learningData)return simpleLearning(page);if(page==='results'||page==='feedback'||page==='work')return `<div class="panel"><h2>${t('Learning results','ผลการเรียน')}</h2>${learningData.submissions.map(s=>`<article class="admin-item"><b>${s.score===null?t('Awaiting grading','รอตรวจ'):s.score+'%'}</b><p>${esc(s.feedback||'')}</p></article>`).join('')||empty(t('No results yet','ยังไม่มีผลการเรียน'),t('Results appear after assessment submission.','ผลจะแสดงหลังส่งแบบทดสอบ'))}</div>`;
if(page==='assessments'&&realRole()==='student')return `<div class="panel"><h2>${t('Assessments','แบบทดสอบ')}</h2>${learningData.assessments.map(a=>`<form class="admin-item" data-take-assessment="${a.id}"><h3>${esc(tx(a.title))}</h3><p>${t('Pass score','คะแนนผ่าน')}: ${a.passScore}% · ${t('Attempts allowed','จำนวนครั้งที่อนุญาต')}: ${a.attemptLimit}</p>${a.questions.map((q,i)=>`<fieldset><legend>${i+1}. ${esc(tx(q.prompt))}</legend>${q.type==='written'?`<textarea name="q${i}" required maxlength="6000" aria-label="${t('Answer','คำตอบ')}"></textarea>`:q.options.map((o,n)=>`<label class="question-option"><input type="radio" name="q${i}" value="${n}" required>${esc(tx(o))}</label>`).join('')}</fieldset>`).join('')}<div class="form-error" role="alert"></div><button class="primary">${t('Submit assessment','ส่งแบบทดสอบ')}</button></form>`).join('')||empty(t('No available assessments','ยังไม่มีแบบทดสอบ'),t('Your teacher will publish assessments for assigned courses.','ครูจะเผยแพร่แบบทดสอบในหลักสูตรที่มอบหมาย'))}</div>`;
let html=simpleLearning(page);if(realRole()==='student')for(const c of learningData.courses)for(const l of c.lessons){const done=learningData.progress.some(p=>p.student===session.id&&p.lesson===l.id&&p.completed);const anchor=`<summary>${esc(tx(l.title))}</summary>`;html=html.replace(anchor,anchor+`<p><button class="button small" data-complete-lesson="${l.id}" data-course="${c.id}" ${done?'disabled':''}>${done?t('Completed','เสร็จแล้ว'):t('Mark lesson complete','ทำเครื่องหมายว่าเรียนจบ')}</button></p>`);}return html;};
const productionBind=bind;
bind=function(){productionBind();document.querySelectorAll('[data-grade-submission]').forEach(form=>form.onsubmit=e=>{e.preventDefault();formAction(form,async f=>{await api('/api/admin/grade',{method:'POST',body:JSON.stringify({id:form.dataset.gradeSubmission,score:+f.get('score'),feedback:f.get('feedback')})});schoolData=null;loadSchool(true);});});document.querySelectorAll('[data-take-assessment]').forEach(form=>form.onsubmit=e=>{e.preventDefault();formAction(form,async f=>{const a=learningData.assessments.find(a=>a.id===form.dataset.takeAssessment);const result=await api('/api/learning/submit',{method:'POST',body:JSON.stringify({assessment:a.id,answers:a.questions.map((q,i)=>q.type==='written'?f.get('q'+i):+f.get('q'+i))})});learningData=null;location.hash='portal/results';render();toast(result.score===null?'Submitted for teacher review.':'Assessment submitted.',result.score===null?'ส่งให้ครูตรวจแล้ว':'ส่งแบบทดสอบแล้ว');});});document.querySelectorAll('[data-complete-lesson]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/learning/complete',{method:'POST',body:JSON.stringify({course:b.dataset.course,lesson:b.dataset.completeLesson})});learningData=null;render();}catch(e){b.disabled=false;toast(accountMessage(e.message),accountMessage(e.message));}});};
const productionError=accountMessage;
accountMessage=function(code){if(code==='password_mismatch')return t('The passwords do not match.','รหัสผ่านไม่ตรงกัน');if(code==='attempt_limit')return t('You have used all allowed attempts.','คุณใช้จำนวนครั้งที่อนุญาตครบแล้ว');return productionError(code);};
let publicSchool={courses:[],events:[]};
statusPage=function(){return `<div class="container narrow">${heading(t('System status','สถานะระบบ'),t('School services','บริการโรงเรียน'))}<div class="panel"><h2>${t('School accounts','บัญชีโรงเรียน')}</h2><p>${accountStatus?t('Email/password accounts, protected administrator setup, server sessions and logout are connected.','เชื่อมต่อบัญชีอีเมล/รหัสผ่าน การตั้งค่าผู้ดูแลที่ได้รับการป้องกัน เซสชันเซิร์ฟเวอร์ และการออกจากระบบแล้ว'):t('Account service could not be reached.','ไม่สามารถติดต่อบริการบัญชีได้')}</p><h3>${t('Email delivery','การส่งอีเมล')}</h3><p>${accountStatus?.emailDelivery?t('A provider is configured. Delivery is confirmed separately for each request.','ตั้งค่าผู้ให้บริการแล้ว ยืนยันการจัดส่งแต่ละคำขอแยกกัน'):t('Not configured. Invitation and reset emails are unavailable. Verified site-owner password recovery is available after initial setup.','ยังไม่ได้ตั้งค่า ไม่สามารถส่งอีเมลคำเชิญหรือรีเซ็ตได้ เจ้าของเว็บไซต์ที่ยืนยันตัวตนสามารถกู้คืนรหัสผ่านหลังตั้งค่าเริ่มต้น')}</p><h3>${t('School records','ข้อมูลโรงเรียน')}</h3><p>${t('School accounts, courses, assignments, verified family links, assessments, reports and event registrations use persistent storage. Public sample content and isolated demos remain labeled.','บัญชีโรงเรียน หลักสูตร การมอบหมาย ความสัมพันธ์ครอบครัว แบบทดสอบ รายงาน และการลงทะเบียนกิจกรรมใช้พื้นที่จัดเก็บถาวร เนื้อหาตัวอย่างและระบบสาธิตยังมีป้ายกำกับ')}</p></div></div>`;};
const originalCatalog=catalog,originalEvents=eventsPage;
catalog=function(){if(!publicSchool.courses.length)return originalCatalog();return `<div class="container">${heading(t('Courses','หลักสูตร'),t('Find your next step','ค้นหาก้าวต่อไปของคุณ'))}<div class="three">${publicSchool.courses.map(c=>`<article class="card card-body"><span class="tag">${esc(c.subject)} · ${esc(c.level)}</span><h2>${esc(tx(c.title))}</h2><p>${esc(tx(c.description))}</p><p>${c.lessonCount} ${t('lessons','บทเรียน')} · ${c.minutes} ${t('minutes','นาที')}</p><p>${t('Teaching language','ภาษาที่สอน')}: ${esc(c.language.toUpperCase())}</p><p>${t('Course access is assigned by the school after review.','โรงเรียนมอบหมายสิทธิ์หลักสูตรหลังตรวจสอบ')}</p>${button(t('Contact about this course','ติดต่อเกี่ยวกับหลักสูตร'),'contact')}</article>`).join('')}</div></div>`;};
eventsPage=function(){if(!publicSchool.events.length)return originalEvents();return `<div class="container">${heading(t('Events','กิจกรรม'),t('Learn something together','เรียนรู้สิ่งใหม่ด้วยกัน'))}${publicSchool.events.map(e=>`<article class="panel"><h2>${esc(tx(e.title))}</h2><p>${esc(tx(e.description))}</p><p>${new Date(e.start).toLocaleString(lang==='th'?'th-TH':'en-GB')} · ${esc(tx(e.location))}</p><p>${e.registrations}/${e.capacity} ${t('places filled','ที่นั่ง')} · ${t('Registration closes','ปิดรับลงทะเบียน')}: ${formatted(e.deadline)}</p>${e.registrations>=e.capacity?notice(t('This event is full.','กิจกรรมนี้เต็มแล้ว')):Date.parse(e.deadline)<Date.now()?notice(t('Registration has closed.','ปิดรับลงทะเบียนแล้ว')):session.id?`<button class="primary" data-register-real-event="${e.id}">${t('Register with my school account','ลงทะเบียนด้วยบัญชีโรงเรียนของฉัน')}</button>`:button(t('Log In to register','เข้าสู่ระบบเพื่อลงทะเบียน'),'login')}</article>`).join('')}</div>`;};
const finalBind=bind;bind=function(){finalBind();document.querySelectorAll('[data-register-real-event]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await api('/api/event-register',{method:'POST',body:JSON.stringify({event:b.dataset.registerRealEvent})});b.outerHTML=notice(t('Registration confirmed. Reference: ','ยืนยันการลงทะเบียนแล้ว รหัส: ')+esc(r.id));}catch(e){b.disabled=false;toast(accountMessage(e.message),accountMessage(e.message));}});};
api('/api/catalog').then(d=>{publicSchool=d;if(['courses','events'].includes(route()[0]))render();}).catch(()=>{});
refreshAccounts();render();
